import flask
app = flask.Flask("t")
@app.route("/hi")
def hi():
    return {"msg": "hello " + flask.request.args.get("n", "")}
c = app.test_client()
r = c.get("/hi?n=x")
assert r.status_code == 200, r.status_code
assert r.get_json() == {"msg": "hello x"}, r.get_json()
print("OK")
